import type { Locale } from "@/i18n/routing"
import type { LegalDocument } from "./types"

const en: LegalDocument = {
  title: "Privacy Policy and Cookies",
  effectiveDateLine: "This Privacy Policy is effective as of 3 August 2026.",
  blocks: [
    { type: "paragraph", text: "If you are our customer, newsletter subscriber or website visitor, you entrust us with your personal data. We are responsible for their protection and security. Please familiarise yourself with the protection of personal data, the principles and the rights you have in connection with the GDPR (General Data Protection Regulation). The processing of personal data is further governed by Act No. 110/2019 Coll., on the Processing of Personal Data, as amended. The sending of commercial communications is governed by Act No. 480/2004 Coll., on Certain Information Society Services, as amended. Terms used in this Policy and not defined herein shall have the meanings set forth in the General Terms and Conditions of the Provider (hereinafter the \"Terms and Conditions\"), which are available on the Website. This Policy and the Terms and Conditions are mutually complementary." },
    { type: "heading", text: "Who is the Controller?" },
    { type: "paragraph", text: "We are the company Sanctum Lux Divine SRL, with its registered office at Strada Sănătății 9, Clădirea C2, Sat Păuleștii Noi, Comuna Păulești, 107403 Păulești, Romania, registration number (CUI): 47877852, registered in the Commercial Register (Registrul Comerțului) under file no. J29/710/2023, operating services under the trade name \"The Path of Initiation Prague\" through the website at www.thepathofinitiationprague.com (hereinafter the \"Website\")." },
    { type: "paragraph", text: "We process your personal data as a controller, i.e. we determine how personal data will be processed and for what purpose, for how long, and we select any additional processors who will assist us with the processing." },
    { type: "heading", text: "Contact Details" },
    { type: "paragraph", text: "If you wish to contact us during the processing, you may reach us by e-mail at: radu@thepathofinitiationprague.com or by phone at: +420 792 908 296." },
    { type: "paragraph", text: "A Data Protection Officer has not been appointed, as our organisation is not legally required to designate one." },
    { type: "heading", text: "Declaration" },
    { type: "paragraph", text: "We declare that, as the controller of your personal data, we comply with all statutory obligations required by applicable legislation, in particular the Personal Data Protection Act and the GDPR, and therefore that:" },
    { type: "list", items: [
      "we shall process your personal data only on the basis of a valid legal ground, in particular legitimate interest, performance of a contract, legal obligation or consent granted;",
      "we fulfil our information obligation pursuant to Article 13 of the GDPR prior to the commencement of the processing of personal data;",
      "we shall enable you and support you in exercising and fulfilling your rights under the Personal Data Protection Act and the GDPR.",
    ] },
    { type: "heading", text: "Scope of Personal Data and Purposes of Processing" },
    { type: "paragraph", text: "We process personal data that you provide to us yourself, as well as personal data that we obtain automatically in connection with your visit to our website (in particular through cookies and similar technologies), for the following reasons (to fulfil the following purposes):" },
    { type: "heading", text: "Sources of Personal Data" },
    { type: "paragraph", text: "We obtain the majority of data directly from you, in particular when ordering Services, when communicating with us, when subscribing to the newsletter or when otherwise contacting us. Certain data are obtained automatically when you visit the Website through cookies and similar technologies (see the \"Cookies“ section below). Depending on the nature of the matter, we may also obtain data from public registers or other publicly available sources." },
    { type: "heading", text: "Third-Party Data" },
    { type: "paragraph", text: "When communicating with us or when using the Services, you may also provide us with data concerning other persons, for example a legal guardian of a minor or a person to whom your matter relates. We use such data only to the extent necessary to handle your matter, perform the contract, comply with legal obligations or protect rights. Where appropriate and feasible given the nature of the matter, please inform such persons that you are providing their data to us." },
    { type: "heading", text: "Provision of Services and Performance of the Contract" },
    { type: "paragraph", text: "We necessarily require your personal data in the following scope: name and surname, e-mail address, telephone number, address (city), information about ordered Services and their progress, for the performance of the contract (e.g. reservation and provision of an Individual Session or Course, communication regarding the date and venue). In the course of providing the Services, we also maintain records of your participation in individual Services, records of your study progress (so-called progression tracking) and written records of communication with you, for the purpose of ensuring continuity and quality of the Services provided. We therefore process such data for the duration of the contract and subsequently for the period necessary to protect our legitimate interests." },
    { type: "heading", text: "Processing of Health Data" },
    { type: "paragraph", text: "In the course of providing the Services, we may process data concerning your health status that you disclose to us (in particular information about ongoing treatment, medications used, addictions, pregnancy, epilepsy, anxiety disorders or other physical or mental indispositions). Such data constitute a special category of personal data within the meaning of Article 9 of the GDPR. The legal basis for their processing is your explicit consent (Article 9(2)(a) of the GDPR), which you grant as part of the ordering process. The purpose of processing is exclusively the assessment of suitability and the safe provision of the Services. We process such data only to the extent necessary for the stated purpose and retain them for the duration of the contractual relationship and subsequently for the duration of the limitation periods (generally 3 years from the provision of the Service, unless otherwise stipulated by law). You may withdraw your consent to the processing of health data at any time; withdrawal of consent shall not affect the lawfulness of processing carried out prior to its withdrawal. However, withdrawal of consent may result in the inability to provide the Service or part thereof, if the processing of such data is necessary for the safe provision of the Service." },
    { type: "heading", text: "Compliance with legal obligations, in particular in connection with tax and accounting legislation." },
    { type: "paragraph", text: "If you are a customer, we necessarily require your personal data (billing data) in order to comply with various statutory obligations, in particular those relating to the issuance and record-keeping of tax documents. We process personal data for this purpose for the period stipulated by applicable legislation." },
    { type: "heading", text: "Marketing – Sending Newsletters" },
    { type: "paragraph", text: "We use your personal data (e-mail address and name) for the purpose of direct marketing – sending commercial communications. If you are our customer, we do so on the basis of our legitimate interest, as we reasonably assume that our news is of interest to you, for a period of 5 years from the last order. If you are not our customer, we send you newsletters only on the basis of your consent, for a period of 5 years from the granting thereof or until its withdrawal." },
    { type: "heading", text: "Proper Operation of the Website" },
    { type: "paragraph", text: "For this purpose, we process data relating to the use of our website, such as your IP address and browsing data, as well as personal data obtained from so-called necessary cookies (see below in the \"Cookies\" section). The purpose of processing is to identify you as a visitor when browsing the website or when logging in repeatedly, inter alia to ensure the functioning of our e-shop. The reason for processing is our legitimate interest in ensuring a functional web presentation, and we generally process the data for the duration of your browsing session; however, if we store them for a longer period, it shall be for no more than 2 years." },
    { type: "heading", text: "Customisation of the Website (Preferences)" },
    { type: "paragraph", text: "For this purpose, we process data relating to the use of our website, such as your IP address and browsing data. The purpose of processing is to customise the website to your preferences, such as location, language settings and your device. The reason for processing is our legitimate interest in personalising the website to the specific preferences of customers, and we generally process the data for the duration of your browsing session; however, if we store them for a longer period, it shall be for no more than 2 years. With your consent, we also process personal data obtained from so-called preference cookies for this purpose, which may also involve the transfer of data to third parties (see below in the \"Cookies\" section), for the period during which we have your consent, but for no more than 2 years from the granting thereof." },
    { type: "heading", text: "Website Traffic Analysis (Statistics)" },
    { type: "paragraph", text: "For this purpose, we process data relating to the use of our website, such as your IP address and browsing data. The purpose of processing is to understand how visitors use our website. The reason for processing is our legitimate interest in obtaining information about the use of our website for the purpose of its further development, and we generally process the data for the duration of your browsing session; however, if we store them for a longer period, it shall be for no more than 2 years. With your consent, we also process personal data obtained from so-called statistical cookies for this purpose, which may also involve the transfer of data to third parties (see below in the \"Cookies\" section), for the period during which we have your consent, but for no more than 2 years from the granting thereof." },
    { type: "heading", text: "Promotion and Advertising of Products and Services (Marketing)" },
    { type: "paragraph", text: "For this purpose, we process data relating to the use of our website, such as your IP address and browsing data. The purpose of processing is to obtain information for displaying advertising corresponding to the personal preferences of a specific user and to carry out such advertising. The reason for processing is our legitimate interest in promoting the sale of our products and services, and we generally process the data for the duration of your browsing session; however, if we store them for a longer period, it shall be for no more than 2 years. With your consent, we also process personal data obtained from so-called marketing cookies for this purpose, which may also involve the transfer of data to third parties (see below in the \"Cookies\" section), for the period during which we have your consent, but for no more than 2 years from the granting thereof." },
    { type: "heading", text: "Internal Records and Protection of Our Rights and Interests" },
    { type: "paragraph", text: "For this purpose, we process in particular your identification data, data on the use of products and services or billing data, in order to safeguard our legitimate interests, specifically the maintenance of our internal records and the monitoring of the proper provision of our services, as well as the protection of our rights and legal claims. For this purpose, we process your personal data for the duration of the limitation period, including any period covering its suspension or interruption, but typically for no longer than 15 years after the delivery of goods or the provision of a service or digital content. If judicial, administrative or other proceedings are commenced, we shall process your personal data to the necessary extent also for the entire duration of such proceedings for the purpose of exercising or defending our legal claims." },
    { type: "heading", text: "Photographs and Video Recordings from Seminars" },
    { type: "paragraph", text: "At some of our courses and other services, we produce photographic documentation or video recordings. We use photographs and recordings in promotional materials, primarily on the Website and social media. The legal basis for producing and using such recordings is our legitimate interest in promoting our Services. You will be informed about the production of recordings prior to the commencement of the relevant Service. We never disclose the names of participants in connection with such materials, unless it constitutes a testimonial, and then exclusively on the basis of your consent. You have the right to object to the processing of your personal data for these purposes; if you do not wish to be captured in the recordings, please contact us at our contact details prior to the relevant event." },
    { type: "heading", text: "Is the Provision of Data Mandatory?" },
    { type: "paragraph", text: "Visiting the Website is voluntary. If you wish to order Services, we require at least such data as are necessary for us to process your order. Without them, we may not be able to conclude a contract or provide the Service. We are required by law to process certain data, for example for accounting or tax purposes. Consent to the sending of commercial communications, analytical or marketing cookies or to the processing of health data is voluntary. If you do not grant such consent, this shall not affect your ability to order Services or the basic functionality of the Website." },
    { type: "paragraph", text: "We retain your personal data for the duration of the limitation periods (generally 3 years; in the case of rights to compensation for damage to health or rights arising from unjust enrichment, up to 15 years), unless the law stipulates a longer retention period or unless we have stated otherwise in specific cases." },
    { type: "heading", text: "Automated Decision-Making and Profiling" },
    { type: "paragraph", text: "While processing your personal data, no automated decision-making or profiling within the meaning of Article 22 of the GDPR takes place that would produce legal effects concerning you or similarly significantly affect you." },
    { type: "heading", text: "Cookies" },
    { type: "paragraph", text: "We use cookies and similar technologies (pixels, tags, local storage and other online identifiers) on the Website. These technologies are stored on your device or work with information stored therein and help ensure the functioning of the Website, its security, analytics and marketing. We use both cookies that are deleted after you leave the Website and cookies that remain on your device for a set period, but for no longer than 2 years." },
    { type: "heading", text: "Types of cookies, what they are used for, and do we need your consent to use them?" },
    { type: "list", items: [
      "Necessary cookies ensuring the basic functioning, security and correct display of the Website. Without them, the Website may not function properly. We do not need your consent to use them. We use them because they are essential for the operation of the Website.",
      "Analytical cookies that help us determine how visitors use the Website, which pages are visited and what we should improve. Their use is subject to consent and we use them only with your consent.",
      "Marketing cookies that help us evaluate advertising and marketing campaigns, measure conversions and display more relevant content or advertising. Their use is subject to consent and we use them only with your consent.",
    ] },
    { type: "paragraph", text: "Some of the cookies used are necessary for the proper functioning of our web portal, for example for the purpose of identifying a visitor when browsing the website and when logging in repeatedly, securing their access to the web portal or customising its content and marking content that has already been viewed. If a visitor blocks these cookies in their browser, the website may not function properly and it may not be technically possible to provide them with some of our services. These cookies therefore operate on the basis of our legitimate interest for the purpose of the proper functioning of the web portal, as described above." },
    { type: "paragraph", text: "Cookies that are not necessary for the proper functioning of the Website may only be used on the basis of your prior consent. In our case, these may include analytical or marketing cookies, the related processing purposes of which are described above. You may consent to them through the so-called cookie bar on the Website. Analytical and marketing cookies are not active until you grant your consent. You may change or withdraw your consent at any time in the cookie settings on the Website. Refusal or withdrawal of consent must be as easy as granting it. If you refuse analytical or marketing cookies, the Website will continue to function for you; however, we will not have as much information about how the Website is used and we will not be able to customise marketing content for you." },
    { type: "paragraph", text: "You may disable the use of cookies on your computer in your internet browser." },
    { type: "heading", text: "Security and Protection of Personal Data" },
    { type: "paragraph", text: "We protect personal data to the maximum extent possible using modern technologies corresponding to the current state of technical development. We have adopted and maintain technical and organisational measures to secure your personal data within the meaning of Article 32 of the GDPR, which prevent unauthorised access, misuse, damage or destruction of your personal data. These measures include, in particular, encryption of devices and storage, two-factor authentication, a strong password policy, regular data backups and restriction of access to personal data to authorised persons only. We regularly review and update the measures adopted with regard to the current state of technology and the level of risk." },
    { type: "heading", text: "Transfer of Personal Data to Third Parties" },
    { type: "paragraph", text: "Our employees and collaborators, who are bound by confidentiality obligations and have been trained in the area of personal data processing security, may have access to your personal data." },
    { type: "paragraph", text: "In order to ensure certain specific processing operations that we are unable to carry out on our own, we use the services and applications of processors who specialise in the relevant processing and comply with the GDPR. We also share your personal data with third parties where this is necessary for the performance of the contract or on the basis of our legitimate interest. These include the providers of the following platforms and services:" },
    { type: "list", items: [
      "Stripe – payment gateway for processing card payments (Stripe does not process personal data on our instructions but as an independent controller; further information can be found in Stripe's privacy policy at stripe.com/privacy)",
      "Modern Mystery School International Inc. (registered in Canada) – we share your name, contact details and history of completed Services for the purpose of study records and intellectual property rights management; MMS International Inc. processes such data as an independent controller. The transfer of data to Canada is carried out on the basis of a European Commission adequacy decision or standard contractual clauses issued by the European Commission (Article 46(2)(c) of the GDPR)",
      "Microsoft (OneDrive) – cloud storage for internal records and data retention",
      "Vercel.com and Google (Gemini) – operation of the AI chat assistant on the Website. Please note that through the chat window on the Website you are communicating with an automated system using artificial intelligence (AI), not with a natural person. Data that you enter into the chat window (in particular the text of your queries) are transferred to Vercel Inc. (USA) and Google LLC (USA) for the purpose of generating responses. The legal basis for this processing is our legitimate interest in providing an information service to Website visitors. Data entered into the chat window are processed for the period necessary to generate a response and may be retained by the service providers in accordance with their own privacy policies. We recommend that you do not enter sensitive personal data into the chat window (in particular health data, financial data, etc.). The transfer of data to the USA is ensured on the basis of the EU-US Data Privacy Framework, provided that the relevant recipient is certified, or alternatively on the basis of standard contractual clauses",
      "WhatsApp (Meta Platforms, Inc.) – communication platform used for communication with customers; Meta processes personal data as an independent controller; further information can be found in Meta's privacy policy at https://www.whatsapp.com/legal/privacy-policy",
    ] },
    { type: "paragraph", text: "It is possible that in the future we may decide to use additional applications or processors to facilitate and improve the quality of processing. However, we undertake that in such case, when selecting processors, we shall impose at least the same requirements for security and quality of processing as we impose on ourselves." },
    { type: "heading", text: "Transfer of Data Outside the European Union" },
    { type: "paragraph", text: "We process data primarily within the European Union or in countries that ensure an adequate level of protection on the basis of a European Commission decision. However, your data may also be transferred to third countries outside the European Union, typically to the companies Modern Mystery School International Inc., Vercel.com, Google or Microsoft, which may have their registered offices or servers outside the EU. In the case of data transfers to the USA, an adequate level of protection may be ensured on the basis of the European Commission's adequacy decision under the EU-US Data Privacy Framework, provided that the relevant recipient is certified. All other transfers of data outside the EU shall be carried out only where an appropriate legal basis exists, in particular a European Commission adequacy decision, standard contractual clauses issued by the European Commission or another appropriate safeguard mechanism within the meaning of Article 46 of the GDPR." },
    { type: "heading", text: "Your Rights in Connection with the Protection of Personal Data" },
    { type: "paragraph", text: "In connection with the protection of personal data, you have a number of rights. If you wish to exercise any of these rights, please contact us by e-mail at: radu@thepathofinitiationprague.com. We shall respond to your request without undue delay, generally no later than within one (1) month. In justified cases, we may extend this period by a further two (2) months in accordance with the GDPR, of which we shall inform you. In order to protect your data, we may verify your identity in a reasonable manner. You have the right to information, which is fulfilled by this information page on the principles of personal data processing." },
    { type: "paragraph", text: "Right of Access (Article 15 of the GDPR): By virtue of the right of access, you may request at any time that we demonstrate, within a period of one (1) month, what personal data of yours we process and why, as well as information about our processing of such data. In exceptional cases, in particular due to the complexity or number of requests, we are entitled to extend this period by a further two (2) months, of which we shall inform you. If you so request, you may also receive a copy of your personal data: the first copy is free of charge; each additional copy may, however, be subject to a reasonable administrative fee." },
    { type: "paragraph", text: "Right to Rectification (Article 16 of the GDPR): If your circumstances change or you find your personal data to be inaccurate or incomplete, you have the right to have your personal data supplemented and amended." },
    { type: "paragraph", text: "Right to Restriction of Processing (Article 18 of the GDPR): You may exercise the right to restriction of processing if you believe that we are processing inaccurate data about you, if you believe that we are carrying out processing unlawfully but you do not wish to have all data erased, or if you have raised an objection to the processing." },
    { type: "paragraph", text: "You may restrict the scope of personal data or the purposes of processing. (For example, by unsubscribing from the newsletter, you restrict the purpose of processing for the sending of commercial communications.)" },
    { type: "paragraph", text: "Right to Data Portability (Article 20 of the GDPR): You have the right to data portability, i.e. you may obtain from us all your personal data that you yourself have provided to us and that we process on the basis of your consent or on the basis of the performance of a contract, provided that the processing is carried out by automated means. We shall provide such data to you in a structured, commonly used and machine-readable format. You also have the right to request that we transfer such data directly to another controller, where technically feasible." },
    { type: "paragraph", text: "Right to Object (Article 21 of the GDPR): You may raise objections to the processing of personal data that takes place on the basis of our legitimate interest. Where marketing activities are concerned, we shall cease processing your personal data without further ado; in other cases, we shall do so unless we have compelling legitimate grounds to continue such processing." },
    { type: "paragraph", text: "Right to Withdraw Consent: Where the processing of your personal data is based on your consent, you have the right to withdraw such consent at any time, without stating a reason. Withdrawal of consent shall not affect the lawfulness of processing based on consent granted prior to its withdrawal. You may withdraw your consent by e-mail at: radu@thepathofinitiationprague.com or through the unsubscribe link in the e-mails sent." },
    { type: "heading", text: "Right to Erasure (Article 17 of the GDPR)" },
    { type: "paragraph", text: "You have the right to request the erasure of your personal data, provided that the statutory conditions set out in Article 17 of the GDPR are met. In such case, we shall erase all your personal data from our system and from the systems of all sub-processors and backups. To ensure the right to erasure, we require a period of one (1) month; in exceptional cases, we are entitled to extend this period by a further two (2) months, of which we shall inform you." },
    { type: "paragraph", text: "In certain cases, we are bound by a statutory obligation and, for example, must retain issued tax documents for the period stipulated by law. In such case, we shall therefore erase all such personal data that are not subject to another statutory obligation or for which we do not have another purpose for which we may continue to legitimately process them, typically for the establishment, exercise or defence of our legal claims. We shall inform you of the completion of the erasure by e-mail." },
    { type: "heading", text: "Protection of Children's Personal Data" },
    { type: "paragraph", text: "Our Services are primarily intended for adults. As part of our offering, we also provide a baby blessing ceremony for children aged 0–5 years and their mothers; in such case, we process the child's personal data on the basis of the legal guardian's consent. Persons over the age of 15 may participate in our Services and their personal data may be processed on the basis of their own consent. In the case of a person under the age of 15, the processing of personal data on the basis of consent is permissible only if the consent is given or approved by the legal guardian of such person. The participation of a minor (a person under the age of 18) in our Services is conditional upon the consent of their legal guardian and the minor's own will. If we discover that we are processing personal data of a person under the age of 15 without the consent of their legal guardian, we shall take immediate measures to erase such data. In such case, please contact us at the e-mail address: radu@thepathofinitiationprague.com." },
    { type: "heading", text: "Complaint to a Supervisory Authority" },
    { type: "paragraph", text: "If you believe that we are not handling your data in accordance with the law, you have the right, in accordance with Article 77 of the GDPR, to lodge a complaint with a supervisory authority, in particular in the Member State of your habitual residence, place of work or place of the alleged infringement. The lead supervisory authority for our company is the Autoritatea Națională de Supraveghere a Prelucrării Datelor cu Caracter Personal (ANSPDCP), with its registered office at B-dul G-ral. Gheorghe Magheru 28-30, Sector 1, 010336 București, Romania (www.dataprotection.ro). If you are resident in the Czech Republic, you may also contact the Office for Personal Data Protection (Úřad pro ochranu osobních údajů), with its registered office at Pplk. Sochora 27, 170 00 Prague 7 (www.uoou.cz). A list of supervisory authorities of the Member States is available on the website of the European Data Protection Board (https://edpb.europa.eu/about-edpb/about-edpb/members_en). We would appreciate it if you would first inform us of such suspicion so that we may investigate and remedy any potential shortcomings." },
    { type: "heading", text: "Unsubscribing from Newsletters and Commercial Communications" },
    { type: "paragraph", text: "We send you e-mails with inspiration, articles or products and services, if you are our customer, on the basis of our legitimate interest in accordance with Section 7(3) of Act No. 480/2004 Coll., on Certain Information Society Services. If you are not yet a customer, we send them to you only on the basis of your consent. In both cases, you may unsubscribe from our e-mails by clicking the unsubscribe link in each e-mail sent." },
    { type: "heading", text: "Confidentiality" },
    { type: "paragraph", text: "We wish to assure you that our employees and collaborators who will process your personal data are obliged to maintain confidentiality regarding personal data and regarding security measures the disclosure of which would jeopardise the security of your personal data. This confidentiality obligation shall continue even after the termination of their contractual relationships with us. Without your consent, your personal data shall not be disclosed to any third party beyond the processors specified in this Policy and cases where disclosure is required by applicable legislation." },
    { type: "paragraph", text: "This Privacy Policy is effective as of 3 August 2026" },
  ],
}

const cs: LegalDocument = {
  title: "Zásady ochrany osobních údajů a cookies",
  effectiveDateLine: "Tyto zásady zpracování osobních údajů platí od 3. srpna 2026.",
  blocks: [
    { type: "paragraph", text: "Pokud jste naším zákazníkem, odběratelem novinek nebo návštěvníkem webu, svěřujete nám své osobní údaje. My zodpovídáme za jejich ochranu a zabezpečení. Seznamte se, prosíme, s ochranou osobních údajů, zásadami a právy, které máte v souvislosti s GDPR (Obecné nařízení o ochraně osobních údajů). Zpracování osobních údajů se dále řídí zákonem č. 110/2019 Sb., o zpracování osobních údajů, ve znění pozdějších předpisů. Zasílání obchodních sdělení se řídí zákonem č. 480/2004 Sb., o některých službách informační společnosti, ve znění pozdějších předpisů. Pojmy použité v těchto zásadách a nedefinované v nich mají význam stanovený ve Všeobecných obchodních podmínkách Poskytovatele (dále jen „Podmínky“), které jsou dostupné na Webu. Tyto zásady a Podmínky se vzájemně doplňují." },
    { type: "heading", text: "Kdo je správce?" },
    { type: "paragraph", text: "Jsme společnost Sanctum Lux Divine SRL, se sídlem Strada Sănătății 9, Clădirea C2Sat Păuleștii Noi, Comuna Păulești, 107403 Păulești, Rumunsko, registrační číslo (CUI): 47877852, zapsaná v obchodním rejstříku (Registrul Comerțului) pod sp. zn. J29/710/2023, provozující služby pod obchodní značkou „The Path of Initiation Prague\" prostřednictvím webových stránek na adrese www.thepathofinitiationprague.com (dále jen „Web“)." },
    { type: "paragraph", text: "Vaše osobní údaje zpracováváme jako správce, tj. určujeme, jak budou osobní údaje zpracovávány a za jakým účelem, po jak dlouhou dobu a vybíráme případné další zpracovatele, kteří nám se zpracováním budou pomáhat." },
    { type: "heading", text: "Kontaktní údaje" },
    { type: "paragraph", text: "Pokud se na nás budete chtít v průběhu zpracování obrátit, můžete nás kontaktovat na e-mailu: radu@thepathofinitiationprague.com nebo telefonicky na čísle: +420 792 908 296." },
    { type: "paragraph", text: "Pověřenec pro ochranu osobních údajů nebyl jmenován, neboť naše organizace nemá zákonnou povinnost jej ustanovit." },
    { type: "heading", text: "Prohlášení" },
    { type: "paragraph", text: "Prohlašujeme, že jako správce Vašich osobních údajů splňujeme veškeré zákonné povinnosti vyžadované platnou legislativou, zejména zákonem o ochraně osobních údajů a GDPR, a tedy že:" },
    { type: "list", items: [
      "budeme zpracovávat Vaše osobní údaje jen na základě platného právního důvodu, a to především oprávněného zájmu, plnění smlouvy, zákonné povinnosti či uděleného souhlasu,",
      "plníme dle článku 13 GDPR informační povinnost ještě před zahájením zpracování osobních údajů,",
      "umožníme Vám a budeme Vás podporovat v uplatňování a plnění Vašich práv podle zákona o ochraně osobních údajů a GDPR.",
    ] },
    { type: "heading", text: "Rozsah osobních údajů a účely zpracování" },
    { type: "paragraph", text: "Zpracováváme osobní údaje, které nám svěříte sami, jakož i osobní údaje, které získáváme automaticky v souvislosti s Vaší návštěvou našich webových stránek (zejména prostřednictvím cookies a obdobných technologií), a to z následujících důvodů (pro naplnění těchto účelů):" },
    { type: "heading", text: "Odkud osobní údaje získáváme" },
    { type: "paragraph", text: "Většinu údajů získáváme přímo od Vás, zejména při objednávce Služeb, při komunikaci s námi, při přihlášení k odběru newsletteru nebo při jiném kontaktu. Některé údaje získáváme automaticky při návštěvě Webu prostřednictvím cookies a obdobných technologií (viz kapitola „Cookies“ níže). Podle povahy věci můžeme údaje získat také z veřejných rejstříků nebo jiných veřejně dostupných zdrojů." },
    { type: "heading", text: "Údaje třetích osob" },
    { type: "paragraph", text: "Při komunikaci s námi nebo při využívání Služeb nám můžete sdělit také údaje o jiných osobách, například o zákonném zástupci nezletilé osoby nebo o osobě, které se Vaše záležitost týká. Takové údaje používáme jen v rozsahu potřebném k vyřízení Vaší záležitosti, plnění smlouvy, splnění právních povinností nebo ochraně práv. Pokud je to s ohledem na povahu věci vhodné a možné, informujte prosím tyto osoby o tom, že nám jejich údaje předáváte." },
    { type: "heading", text: "Poskytování služeb a plnění smlouvy" },
    { type: "paragraph", text: "Vaše osobní údaje v rozsahu: jméno a příjmení, e-mail, telefonní číslo, adresa (město), údaje o objednaných Službách a jejich průběhu nezbytně potřebujeme k plnění smlouvy (např. rezervace a poskytnutí Individuálního sezení nebo Kurzu, komunikace ohledně termínu a místa konání). V rámci poskytování Služeb vedeme rovněž záznamy o Vaší účasti na jednotlivých Službách, o průběhu Vašeho studia (tzv. progression tracking) a písemné záznamy z komunikace s Vámi, a to za účelem zajištění návaznosti a kvality poskytovaných Služeb. Zpracováváme je tedy po dobu účinnosti smlouvy a dále po dobu nezbytnou k ochraně našich oprávněných zájmů." },
    { type: "heading", text: "Zpracování údajů o zdravotním stavu" },
    { type: "paragraph", text: "V rámci poskytování Služeb můžeme zpracovávat údaje o Vašem zdravotním stavu, které nám sdělíte (zejména informace o probíhající léčbě, užívaných lécích, závislostech, těhotenství, epilepsii, úzkostných stavech nebo jiných fyzických či psychických indispozicích). Tyto údaje představují zvláštní kategorii osobních údajů ve smyslu čl. 9 GDPR. Právním základem pro jejich zpracování je Váš výslovný souhlas (čl. 9 odst. 2 písm. a) GDPR), který udělujete v rámci objednávkového procesu. Účelem zpracování je výhradně posouzení vhodnosti a bezpečné poskytování Služeb. Tyto údaje zpracováváme pouze v rozsahu nezbytném pro uvedený účel a uchováváme je po dobu trvání smluvního vztahu a dále po dobu běhu promlčecích lhůt (zpravidla 3 roky od poskytnutí Služby, není-li zákonem stanoveno jinak). Svůj souhlas se zpracováním údajů o zdravotním stavu můžete kdykoli odvolat; odvolání souhlasu nemá vliv na zákonnost zpracování provedeného před jeho odvoláním. Odvolání souhlasu však může mít za následek nemožnost poskytnutí Služby nebo její části, pokud je zpracování těchto údajů nezbytné pro bezpečné poskytování Služby." },
    { type: "heading", text: "Plnění právních povinností zejm. v souvislosti s daňovými a účetními zákony." },
    { type: "paragraph", text: "Jste-li zákazníky, Vaše osobní údaje (fakturační údaje) nezbytně potřebujeme, abychom vyhověli různým zákonným povinnostem zejm. týkající se vystavování a evidence daňových dokladů. Osobní údaje takto zpracováváme po dobu stanovenou právními předpisy." },
    { type: "heading", text: "Marketing – zasílání newsletterů" },
    { type: "paragraph", text: "Vaše osobní údaje (e-mail a jméno) využíváme za účelem přímého marketingu – zasílání obchodních sdělení. Jste-li naším zákazníkem, děláme tak z oprávněného zájmu, neboť důvodně předpokládáme, že Vás naše novinky zajímají, a to po dobu 5 let od poslední objednávky. Pokud nejste naším zákazníkem, zasíláme Vám newslettery jen na základě Vašeho souhlasu, po dobu 5 let od udělení nebo do jeho odvolání." },
    { type: "heading", text: "Řádný provoz webových stránek" },
    { type: "paragraph", text: "Za tímto účelem zpracováváme údaje o užívání našich webových stránek, jako například Vaši IP adresu a údaje o procházení webu, stejně jako osobní údaje získané z tzv. nezbytných cookies (k tomuto srov. níže v kapitole „Cookies“). Účelem zpracování je identifikace Vás jako návštěvníka při procházení webu anebo při opakovaném přihlášení se na web, a to mimo jiné pro zajištění funkce našeho e-shopu. Důvodem zpracování je náš oprávněný zájem na zajištění funkční webové prezentace a údaje zpracováváme zpravidla po dobu Vašeho procházení webu, pokud je však ukládáme na delší dobu, tak nejdéle po 2 roky." },
    { type: "heading", text: "Přizpůsobení webových stránek (preference)" },
    { type: "paragraph", text: "Za tímto účelem zpracováváme údaje o užívání našich webových stránek, jako například Vaši IP adresu a údaje o procházení webu. Účelem zpracování je přizpůsobování webových stránek Vašim preferencím, například lokalitě, jazykovým volbám a Vašemu zařízení. Důvodem zpracování je náš oprávněný zájem na personalizaci webových stránek konkrétním preferencím zákazníků a údaje zpracováváme zpravidla po dobu Vašeho procházení webu, pokud je však ukládáme na delší dobu, tak nejdéle po 2 roky. V případě Vašeho souhlasu zpracováváme pro tento účel také osobní údaje získané z tzv. preferenčních cookies, kdy může docházet také k předávání údajů 3. stranám (k tomuto srov. níže v kapitole „Cookies“), a to po dobu, po kterou máme Váš souhlas, nejdéle však po 2 roky od jeho udělení." },
    { type: "heading", text: "Analýza návštěvnosti webových stránek (statistika)" },
    { type: "paragraph", text: "Za tímto účelem zpracováváme údaje o užívání našich webových stránek, jako například Vaši IP adresu a údaje o procházení webu. Účelem zpracování je pochopení způsobu, jakým návštěvníci používají naše webové stránky. Důvodem zpracování je náš oprávněný zájem na získání informací o užívání našich stránek za účelem jejich dalšího rozvoje a údaje zpracováváme zpravidla po dobu Vašeho procházení webu, pokud je však ukládáme na delší dobu, tak nejdéle po 2 roky. V případě Vašeho souhlasu zpracováváme pro tento účel také osobní údaje získané z tzv. statistických cookies, kdy může docházet také k předávání údajů 3. stranám (k tomuto srov. níže v kapitole „Cookies“), a to po dobu, po kterou máme Váš souhlas, nejdéle však po 2 roky od jeho udělení." },
    { type: "heading", text: "Podpora a propagace produktů a služeb (marketing)" },
    { type: "paragraph", text: "Za tímto účelem zpracováváme údaje o užívání našich webových stránek, jako například Vaši IP adresu a údaje o procházení webu. Účelem zpracování je získání informací pro zobrazení reklamy odpovídající osobním preferencím konkrétního uživatele a realizace této reklamy. Důvodem zpracování je náš oprávněný zájem na podpoře prodeje našich produktů a služeb a údaje zpracováváme zpravidla po dobu Vašeho procházení webu, pokud je však ukládáme na delší dobu, tak nejdéle po 2 roky. V případě Vašeho souhlasu zpracováváme pro tento účel také osobní údaje získané z tzv. marketingových cookies, kdy může docházet také k předávání údajů 3. stranám (k tomuto srov. níže v kapitole „Cookies“), a to po dobu, po kterou máme Váš souhlas, nejdéle však po 2 roky od jeho udělení." },
    { type: "heading", text: "Interní evidence a ochrana našich práv a zájmů" },
    { type: "paragraph", text: "Za tímto účelem zpracováváme zejm. Vaše identifikační údaje, údaje o využívání produktů a služeb nebo fakturační údaje, a to pro zajištění našich oprávněných zájmů, konkrétně vedení naší vnitřní evidence a kontrola řádného poskytování našich služeb, jakož i ochrana našich práv a právních nároků. Pro tento účel Vaše osobní údaje zpracováváme po dobu trvání promlčecí doby, včetně doby pokrývající její případné stavení či přerušení, typicky však ne déle než 15 let po dodání zboží či poskytnutí služby nebo digitálního obsahu. V případě zahájení soudního, správního nebo jiného řízení zpracováváme Vaše osobní údaje v nezbytném rozsahu také po celou dobu trvání takových řízení z důvodu výkonu nebo obhajoby našich právních nároků." },
    { type: "heading", text: "Fotografie a video záznamy ze seminářů" },
    { type: "paragraph", text: "Na některých našich kurzech a dalších službách pořizujeme fotografickou dokumentaci či video záznam. Fotografie a záznamy používáme v propagačních materiálech, především na Webu a sociálních sítích. Právním základem pro pořizování a užívání těchto záznamů je náš oprávněný zájem na propagaci našich Služeb. O pořizování záznamů budete informováni před zahájením příslušné Služby. U těchto materiálů nikdy neuvádíme jména účastníků, jedině pokud by se jednalo o referenci, a to výhradně na základě Vašeho souhlasu. Máte právo vznést námitku proti zpracování Vašich osobních údajů pro tyto účely; pokud si nepřejete být na záznamech zachyceni, kontaktujte nás prosím na našich kontaktních údajích před konáním příslušné akce." },
    { type: "heading", text: "Je poskytnutí údajů povinné?" },
    { type: "paragraph", text: "Návštěva Webu je dobrovolná. Pokud si přejete objednat Služby, potřebujeme od Vás alespoň takové údaje, abychom mohli Vaši objednávku vyřídit. Bez nich nemusíme být schopni uzavřít smlouvu nebo poskytnout Službu. Některé údaje jsme povinni zpracovávat ze zákona, například pro účetní nebo daňové účely. Souhlas se zasíláním obchodních sdělení, analytickými či marketingovými cookies nebo se zpracováním údajů o zdravotním stavu je dobrovolný. Pokud jej neudělíte, nemá to vliv na možnost objednání Služeb ani na základní funkčnost Webu." },
    { type: "paragraph", text: "Vaše osobní údaje si ponecháváme po dobu běhu promlčecích lhůt (zpravidla 3 roky, v případě práv na náhradu újmy na zdraví nebo práv z bezdůvodného obohacení až 15 let), pokud zákon nestanoví delší dobu k jejich uchování nebo jsme v konkrétních případech neuvedli jinak." },
    { type: "heading", text: "Automatizované rozhodování a profilování" },
    { type: "paragraph", text: "V rámci zpracování Vašich osobních údajů nedochází k automatizovanému rozhodování ani k profilování ve smyslu čl. 22 GDPR, které by pro Vás mělo právní účinky nebo by se Vás obdobným způsobem dotýkalo." },
    { type: "heading", text: "Cookies" },
    { type: "paragraph", text: "Na Webu používáme cookies a obdobné technologie (zejména pixels, tagy, lokální úložiště a další online identifikátory). Tyto technologie se ukládají ve Vašem zařízení nebo pracují s informacemi v něm uloženými a pomáhají zajistit fungování Webu, jeho bezpečnost, analytiku a marketing. Užíváme jak cookies, které se vymažou po ukončení návštěvy Webu, tak cookies, které zůstávají na Vašem zařízení po nastavenou dobu, nejdéle však po 2 roky." },
    { type: "heading", text: "Typy cookies,  k čemu slouží, potřebujeme k jejich použití souhlas?" },
    { type: "list", items: [
      "Nezbytné cookies zajišťující základní fungování, bezpečnost a správné zobrazení Webu. Bez nich by Web nemusel fungovat správně. K jejich použití souhlas nepotřebujeme. Používáme je proto, že jsou pro provoz Webu nezbytné.",
      "Analytické cookies které nám pomáhají nám zjistit, jak návštěvníci Web používají, které stránky jsou navštěvované a co máme zlepšit. Jejich použití je podmíněno souhlasem a používáme je jen po Vašem souhlasu.",
      "Marketingové cookies které nám pomáhají vyhodnocovat reklamu a marketingové kampaně, měřit konverze a zobrazovat relevantnější obsah nebo reklamu. Jejich použití je podmíněno souhlasem a používáme je jen po Vašem souhlasu.",
    ] },
    { type: "paragraph", text: "Některé z užívaných cookies jsou nezbytné pro správné fungování našeho webového portálu, například za účelem identifikace návštěvníka při procházení webu a jeho opakovaném přihlášení se na web, zabezpečení jeho přístupu do webového portálu či přizpůsobení jeho obsahu a označení obsahu, který si již prohlédl. Pokud si návštěvník v prohlížeči tyto cookies zablokuje, nemusí web fungovat správně ani nemusí být technicky možné poskytnout mu některé z našich služeb. Tyto cookies tedy fungují na základě našeho oprávněného zájmu pro účel řádného fungování webového portálu, jak je tento popsán výše." },
    { type: "paragraph", text: "Cookies, které pro správné fungování Webu nezbytné nejsou, mohou být užívány pouze na základě Vašeho předchozího souhlasu. V našem případě může jít o analytické nebo marketingové cookies, kdy související účely zpracování jsou popsány výše. Souhlasit s nimi lze skrze tzv. cookies lištu na Webu. Analytické a marketingové cookies nejsou aktivní, dokud k nim neudělíte souhlas. Souhlas můžete kdykoliv změnit nebo odvolat v nastavení cookies na Webu. Odmítnutí nebo odvolání souhlasu musí být stejně jednoduché jako jeho udělení. Pokud analytické nebo marketingové cookies odmítnete, Web pro Vás bude dál fungovat; jen nebudeme mít tolik informací o tom, jak se Web používá, a nebudeme Vám moci přizpůsobovat marketingový obsah." },
    { type: "paragraph", text: "Používání cookies můžete na svém počítači v internetovém prohlížeči zakázat." },
    { type: "heading", text: "Zabezpečení a ochrana osobních údajů" },
    { type: "paragraph", text: "Chráníme osobní údaje v maximální možné míře pomocí moderních technologií, které odpovídají stupni technického rozvoje. Přijali jsme a udržujeme technická a organizační opatření k zabezpečení Vašich osobních údajů ve smyslu čl. 32 GDPR, která zamezují neoprávněnému přístupu, zneužití, poškození nebo zničení Vašich osobních údajů. Tato opatření zahrnují zejména šifrování zařízení a úložišť, dvoufaktorové ověření přístupu, politiku silných hesel, pravidelné zálohování dat a omezení přístupu k osobním údajům pouze na oprávněné osoby. Přijatá opatření pravidelně přezkoumáváme a aktualizujeme s ohledem na aktuální stav techniky a míru rizika." },
    { type: "heading", text: "Předání osobních údajů třetím osobám" },
    { type: "paragraph", text: "K Vašim osobním údajům mohou mít přístup naši zaměstnanci a spolupracovníci, kteří jsou vázáni mlčenlivostí a proškoleni v oblasti bezpečnosti zpracování osobních údajů." },
    { type: "paragraph", text: "Pro zajištění některých konkrétních zpracovatelských operací, které nedokážeme zajistit vlastními silami, využíváme služeb a aplikací zpracovatelů, kteří se na dané zpracování specializují a jsou v souladu s GDPR. Vaše osobní údaje rovněž sdílíme s třetími stranami, je-li to nezbytné pro plnění smlouvy nebo na základě našeho oprávněného zájmu. Jedná se o poskytovatele následujících platforem a služeb:" },
    { type: "list", items: [
      "Stripe – platební brána pro zpracování plateb kartou (Stripe nezpracovává osobní údaje na náš pokyn, ale jako samostatný správce; bližší informace naleznete v zásadách ochrany soukromí společnosti Stripe na stripe.com/privacy)",
      "Modern Mystery School International Inc. (se sídlem v Kanadě) – sdílíme jméno, kontaktní údaje a historii absolvovaných Služeb za účelem evidence studia a správy práv duševního vlastnictví; MMS International Inc. zpracovává tyto údaje jako samostatný správce. Předávání údajů do Kanady je uskutečňováno na základě rozhodnutí Evropské komise o odpovídající úrovni ochrany nebo standardních smluvních doložek vydaných Evropskou komisí (čl. 46 odst. 2 písm. c) GDPR)",
      "Microsoft (OneDrive) – cloudové úložiště pro interní evidenci a uchovávání dat",
      "Vercel.com a Google (Gemini) – provoz AI chatovacího asistenta na Webu. Upozorňujeme, že prostřednictvím chatovacího okna na Webu komunikujete s automatizovaným systémem využívajícím umělou inteligenci (AI), nikoli s fyzickou osobou. Údaje, které zadáte do chatovacího okna (zejména text Vašich dotazů), jsou předávány společnostem Vercel Inc. (USA) a Google LLC (USA) za účelem generování odpovědí. Právním základem pro toto zpracování je náš oprávněný zájem na poskytování informačního servisu návštěvníkům Webu. Údaje zadané do chatovacího okna jsou zpracovávány po dobu nezbytnou pro vygenerování odpovědi a mohou být uchovávány poskytovateli služby v souladu s jejich vlastními zásadami ochrany soukromí. Doporučujeme Vám nezadávat do chatovacího okna citlivé osobní údaje (zejména údaje o zdravotním stavu, finanční údaje apod.). Předávání údajů do USA je zajištěno na základě EU-US Data Privacy Framework, je-li příslušný příjemce certifikován, případně na základě standardních smluvních doložek",
      "WhatsApp (Meta Platforms, Inc.) – komunikační platforma využívaná pro komunikaci se zákazníky; Meta zpracovává osobní údaje jako samostatný správce; bližší informace naleznete v zásadách ochrany soukromí společnosti Meta na https://www.whatsapp.com/legal/privacy-policy",
    ] },
    { type: "paragraph", text: "Je možné, že se v budoucnu rozhodneme využít další aplikace či zpracovatele, pro usnadnění a zkvalitnění zpracování. Slibujeme Vám však, že v takovém případě při výběru, budeme na zpracovatele klást minimálně stejné nároky na zabezpečení a kvalitu zpracování jako na sebe." },
    { type: "heading", text: "Předávání dat mimo Evropskou unii" },
    { type: "paragraph", text: "Data zpracováváme zejména v Evropské unii nebo v zemích, které zajišťují odpovídající úroveň ochrany na základě rozhodnutí Evropské komise. Může však docházet k předávání Vašich údajů také do třetích zemí mimo Evropskou unii, typicky společnostem Modern Mystery School International Inc, Vercel.com, Google nebo Microsoft, které mohou mít sídlo nebo servery mimo EU. V případě předávání údajů do USA může být odpovídající úroveň ochrany zajištěna na základě rozhodnutí Evropské komise o adekvátnosti v rámci EU-US Data Privacy Framework, pokud je příslušný příjemce certifikován. Veškeré další předávání údajů mimo EU budeme uskutečňovat pouze v případě, že existuje odpovídající právní základ, zejména rozhodnutí Evropské komise o odpovídající úrovni ochrany, standardní smluvní doložky vydané Evropskou komisí nebo jiný vhodný záruční mechanismus ve smyslu čl. 46 GDPR." },
    { type: "heading", text: "Vaše práva v souvislosti s ochranou osobních údajů" },
    { type: "paragraph", text: "V souvislosti s ochranou osobních údajů máte řadu práv. Pokud budete chtít některého z těchto práv využít, prosím, kontaktujte nás prostřednictvím e-mailu: radu@thepathofinitiationprague.com. Na žádost odpovíme bez zbytečného odkladu, zpravidla nejpozději do jednoho (1) měsíce. V odůvodněných případech můžeme tuto lhůtu prodloužit o další dva (2) měsíce podle GDPR, o čemž Vás budeme informovat. Abychom chránili Vaše údaje, můžeme přiměřeným způsobem ověřit Vaši totožnost. Máte právo na informace, které je plněno již touto informační stránkou se zásadami zpracování osobních údajů." },
    { type: "paragraph", text: "Právo na přístup (čl. 15 GDPR): Díky právu na přístup nás můžete kdykoli vyzvat a my Vám doložíme ve lhůtě jednoho (1) měsíce, jaké Vaše osobní údaje zpracováváme a proč, jakož i informace o našem zpracování těchto Vašich údajů. Ve výjimečných případech, zejména z důvodu složitosti nebo počtu žádostí, jsme oprávněni tuto lhůtu prodloužit o další dva (2) měsíce, o čemž Vás budeme informovat. Pokud si tak vyžádáte, můžete dostat i kopii Vašich osobních údajů: první je zdarma, každá další však může podléhat přiměřenému administrativnímu poplatku." },
    { type: "paragraph", text: "Právo na opravu (čl. 16 GDPR): Pokud se u Vás něco změní nebo shledáte své osobní údaje neaktuální nebo neúplné, máte právo na doplnění a změnu osobních údajů." },
    { type: "paragraph", text: "Právo na omezení zpracování (čl. 18 GDPR): Právo na omezení zpracování můžete využít, pokud se domníváte, že zpracováváme Vaše nepřesné údaje, domníváte se, že provádíme zpracování nezákonně, ale nechcete všechny údaje smazat nebo pokud jste vznesl/a námitku proti zpracování." },
    { type: "paragraph", text: "Omezit můžete rozsah osobních údajů nebo účelů zpracování. (Např. odhlášením z newsletteru omezujete účel zpracování pro zasílání obchodních sdělení.)" },
    { type: "paragraph", text: "Právo na přenositelnost údajů (čl. 20 GDPR): Máte právo na přenositelnost, tzn. můžete od nás získat všechny Vaše osobní údaje, které jste nám Vy sám/sama poskytl/a a které zpracováváme na základě Vašeho souhlasu nebo na základě plnění smlouvy, a to za předpokladu, že se zpracování provádí automatizovaně. Ty Vám poskytneme ve strukturovaném, běžně používaném a strojově čitelném formátu. Máte rovněž právo požádat, abychom tyto údaje předali přímo jinému správci, je-li to technicky proveditelné." },
    { type: "paragraph", text: "Právo vznést námitku (čl. 21 GDPR): Můžete vznášet námitky proti zpracování osobních údajů, k němuž dochází na základě našeho oprávněného zájmu. Jde-li o marketingové aktivity, přestaneme Vaše osobní údaje zpracovávat bez dalšího; v ostatních případech tak učiníme, pokud nebudeme mít závažné oprávněné důvody pro to, abychom v takovém zpracování pokračovali." },
    { type: "paragraph", text: "Právo odvolat souhlas: Pokud je zpracování Vašich osobních údajů založeno na Vašem souhlasu, máte právo tento souhlas kdykoli odvolat, a to bez uvedení důvodu. Odvolání souhlasu nemá vliv na zákonnost zpracování založeného na souhlasu uděleném před jeho odvoláním. Souhlas můžete odvolat prostřednictvím e-mailu: radu@thepathofinitiationprague.com nebo prostřednictvím odhlašovacího odkazu v zasílaných e-mailech." },
    { type: "heading", text: "Právo na výmaz (čl. 17 GDPR)" },
    { type: "paragraph", text: "Máte právo požadovat výmaz Vašich osobních údajů, pokud jsou splněny zákonné podmínky stanovené v čl. 17 GDPR. V takovém případě vymažeme veškeré Vaše osobní údaje ze svého systému i ze systému všech dílčích zpracovatelů a záloh. Na zajištění práva na výmaz potřebujeme lhůtu jednoho (1) měsíce; ve výjimečných případech jsme oprávněni tuto lhůtu prodloužit o další dva (2) měsíce, o čemž Vás budeme informovat." },
    { type: "paragraph", text: "V některých případech jsme vázáni zákonnou povinností, a např. musíme evidovat vystavené daňové doklady po lhůtu stanovenou zákonem. V tomto případě tedy smažeme všechny takové osobní údaje, které nejsou vázány jiným zákonem anebo nemáme jiný účel, pro který je můžeme nadále legitimně zpracovávat, typicky pro určení, výkon či obhajobu našich právních nároků. O dokončení výmazu Vás budeme informovat na e-mail." },
    { type: "heading", text: "Ochrana osobních údajů dětí" },
    { type: "paragraph", text: "Naše Služby jsou primárně určeny dospělým osobám. V rámci naší nabídky poskytujeme rovněž obřad požehnání (baby blessing ceremony) pro děti ve věku 0–5 let a jejich matky; v takovém případě zpracováváme osobní údaje dítěte na základě souhlasu zákonného zástupce. Osoby starší 15 let se mohou našich Služeb účastnit a jejich osobní údaje mohou být zpracovávány na základě jejich vlastního souhlasu. V případě osoby mladší 15 let je zpracování osobních údajů na základě souhlasu přípustné pouze tehdy, je-li souhlas udělen nebo schválen zákonným zástupcem této osoby. Účast nezletilé osoby (osoby mladší 18 let) na našich Službách je podmíněna souhlasem jejího zákonného zástupce a vlastní vůlí nezletilé osoby. Pokud zjistíme, že zpracováváme osobní údaje osoby mladší 15 let bez souhlasu jejího zákonného zástupce, přijmeme neprodleně opatření k jejich výmazu. V takovém případě nás prosím kontaktujte na e-mailu: radu@thepathofinitiationprague.com." },
    { type: "heading", text: "Stížnost u dozorového úřadu" },
    { type: "paragraph", text: "Pokud máte pocit, že s Vašimi údaji nezacházíme v souladu se zákonem, máte v souladu s článkem 77 GDPR právo podat stížnost u dozorového úřadu, zejména v členském státě svého obvyklého bydliště, místa výkonu práce nebo místa, kde došlo k údajnému porušení. Vedoucím dozorovým úřadem pro naši společnost je Autoritatea Națională de Supraveghere a Prelucrării Datelor cu Caracter Personal (ANSPDCP), se sídlem B-dul G-ral. Gheorghe Magheru 28-30, Sector 1, 010336 București, Rumunsko (www.dataprotection.ro). Pokud máte bydliště v České republice, můžete se rovněž obrátit na Úřad pro ochranu osobních údajů, se sídlem Pplk. Sochora 27, 170 00 Praha 7 (www.uoou.cz). Seznam dozorových úřadů členských států je dostupný na internetových stránkách Evropského sboru pro ochranu osobních údajů (https://edpb.europa.eu/about-edpb/about-edpb/members_en). Budeme rádi, pokud nás nejprve o tomto podezření budete informovat, abychom mohli případné pochybení prověřit a napravit." },
    { type: "heading", text: "Odhlášení ze zasílání newsletterů a obchodních sdělení" },
    { type: "paragraph", text: "E-maily s inspirací, články či produkty a službami Vám zasíláme, jste-li náš zákazník, na základě našeho oprávněného zájmu v souladu s § 7 odst. 3 zákona č. 480/2004 Sb., o některých službách informační společnosti. Pokud zákazníkem ještě nejste, posíláme Vám je jen na základě Vašeho souhlasu. V obou případech můžete ukončit odběr našich e-mailů stisknutím odhlašovacího odkazu v každém zaslaném e-mailu." },
    { type: "heading", text: "Mlčenlivost" },
    { type: "paragraph", text: "Dovolujeme si Vás ujistit, že naši zaměstnanci i spolupracovníci, kteří budou zpracovávat Vaše osobní údaje, jsou povinni zachovávat mlčenlivost o osobních údajích a o bezpečnostních opatřeních, jejichž zveřejnění by ohrozilo zabezpečení Vašich osobních údajů. Tato mlčenlivost přitom trvá i po skončení závazkových vztahů s námi. Bez Vašeho souhlasu nebudou Vaše osobní údaje vydány žádné jiné třetí straně nad rámec zpracovatelů uvedených v těchto zásadách a případů, kdy je předání vyžadováno právními předpisy." },
    { type: "paragraph", text: "Tyto zásady zpracování osobních údajů platí od 3. srpna 2026" },
  ],
}


